 filename=v['file'];assert Path(filename).name==filename and filename.endswith('.py')
 source=(p/filename).read_text(); tree=ast.parse(source);compile(source,filename,'exec')
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert config==v['config']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 init=methods['__init__']
 defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],[ast.literal_eval(n) for n in init.args.defaults]))
 for k,val in config.items():
  default=defaults[k]
  if isinstance(default,tuple):default=list(default)
  assert val==default,(filename,k,val,default)
 imports=[]
 for n in ast.walk(tree):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   imports.extend([a.name.split('.')[0] for a in n.names] if isinstance(n,ast.Import) else [n.module.split('.')[0]])
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):
   assert n.func.id not in {'open','exec','eval','compile','__import__','input'},(filename,'direct IO/dynamic execution')
 assert set(imports)<=allowed_roots,(filename,imports)
 group=config['summary_action_group'];route=config['residual_routing']
 ancestor=(p/f'history_g1_r0027_{group}_summary_{route}.py').read_text()
 atree=ast.parse(ancestor)
 acls=next(n for n in atree.body if isinstance(n,ast.ClassDef))
 amethods={n.name:n for n in acls.body if isinstance(n,ast.FunctionDef)}
 assert methods.keys()==amethods.keys()
 for name in methods:
  if name not in {'__init__','_represent'}:assert ast.dump(methods[name])==ast.dump(amethods[name]),(filename,'changed',name)
 tail='        self.embedding_layer = FeatureEmbeddingDict(feature_map, embedding_dim)'
 assert source.split(tail,1)[1].split('    def _represent',1)[0]==ancestor.split(tail,1)[1].split('    def _represent',1)[0]
 expected_changes=[
  (\"'action_in_pool': False\",\"'action_in_pool': True\"),
  ('action_in_pool=False, action_in_summaries=True,','action_in_pool=True, action_in_summaries=True,'),
  (\"if action_in_pool is not False or action_in_summaries is not True:\\n            raise ValueError('This study isolates action content inside summaries')\", \"if action_in_summaries is not True:\\n            raise ValueError('Select summary action content with summary_action_group')\"),
  (\"needs_action = self.summary_action_group "'!= '"'none'\", \"needs_action = self.action_in_pool or self.summary_action_group "'!= '"'none'\"),
 ]
 expected=ancestor
 for old,new in expected_changes:assert old in expected;expected=expected.replace(old,new,1)
 expected_tree=ast.parse(expected)
 # Only docstrings/comments and the four intended code substitutions may differ.
 tree.body[0].value.value=expected_tree.body[0].value.value
 assert ast.dump(tree)==ast.dump(expected_tree),(filename,'unexpected source difference')
 # Normalize the two factorial selectors only; every other expression must match.
 for n in ast.walk(tree):
  if isinstance(n,ast.Dict):
   for i,key in enumerate(n.keys):
    if isinstance(key,ast.Constant) and key.value in {'summary_action_group','residual_routing'}:n.values[i]=ast.Constant(value='FACTOR')
 for arg,default in zip(init.args.args[-len(init.args.defaults):],init.args.defaults):
  if arg.arg in {'summary_action_group','residual_routing'}:default.value='FACTOR'
 normalized.append(ast.dump(tree))
 assert hashlib.sha256(source.encode()).hexdigest() in v['note']
 print(filename,': syntax, allowed imports/no direct IO, CONFIG/default parity, exact intended delta, unchanged learned construction/methods and source hash pass')
assert len(set(normalized))==1
print('Four modules equal modulo family/readout defaults and CONFIG selectors')
